    def parse_ws_bid_ask(self, ticker: dict, market: Market = None) -> Ticker:
        #
        #     {
        #         A: '0.4087',
        #         B: '0.0020',
        #         E: '1754517402450016',
        #         T: '1754517402449064',
        #         a: '3667.50',
        #         b: '3667.49',
        #         e: 'bookTicker',
        #         s: 'ETH_USDC',
        #         u: 1328288557
        #     }
        #
        marketId = self.safe_string(ticker, 's')
        marketResolved = self.safe_market(marketId, market)
        symbol = self.safe_string(marketResolved, 'symbol')
        microseconds = self.safe_integer(ticker, 'E', 0)
        timestamp = self.parse_to_int(microseconds / 1000)
        ask = self.safe_string(ticker, 'a')
        askVolume = self.safe_string(ticker, 'A')
        bid = self.safe_string(ticker, 'b')
        bidVolume = self.safe_string(ticker, 'B')
        return self.safe_ticker({
            'symbol': symbol,
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'ask': ask,
            'askVolume': askVolume,
            'bid': bid,
            'bidVolume': bidVolume,
            'info': ticker,
        }, marketResolved)

    async def watch_ohlcv(self, symbol: str, timeframe: str = '1m', since: Int = None, limit: Int = None, params: dict = {}) -> list[list]:
        """
        watches historical candlestick data containing the open, high, low, close price, and the volume of a market

        https://docs.backpack.exchange/#tag/Streams/Public/K-Line

        :param str symbol: unified symbol of the market to fetch OHLCV data for
        :param str timeframe: the length of time each candle represents
        :param int [since]: timestamp in ms of the earliest candle to fetch
        :param int [limit]: the maximum amount of candles to fetch
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param boolean [params.stock]: selects stock spot order-book candles, RFQ candles are unsupported
        :param str [params.source]: Venue only
        :returns int[][]: A list of candles ordered as timestamp, open, high, low, close, volume
        """
        query = await self.prepare_ws_stock_params('watchOHLCV', params)
        result = await self.watch_ohlcv_for_symbols([[symbol, timeframe]], since, limit, query)
        return result[symbol][timeframe]

