    def handle_ohlcv(self, client: Client, message: dict):
        #
        #     {
        #         data: {
        #             E: '1754519557526056',
        #             T: '2025-08-07T00:00:00',
        #             X: false,
        #             c: '3680.520000000',
        #             e: 'kline',
        #             h: '3681.370000000',
        #             l: '3667.650000000',
        #             n: 255,
        #             o: '3670.150000000',
        #             s: 'ETH_USDC',
        #             t: '2025-08-06T22:00:00',
        #             v: '62.2621000'
        #         },
        #         stream: 'kline.2h.ETH_USDC'
        #     }
        #
        data = self.safe_dict(message, 'data', {})
        marketId = self.safe_string(data, 's')
        market = self.market(marketId)
        symbol = market['symbol']
        stream = self.safe_string(message, 'stream', '')
        parts = stream.split('.')
        timeframe = self.safe_string(parts, 1, '')
        if not (symbol in self.ohlcvs):
            self.ohlcvs[symbol] = {}
        if not (timeframe in self.ohlcvs[symbol]):
            limit = self.safe_integer(self.options, 'OHLCVLimit', 1000)
            stored = ArrayCacheByTimestamp(limit)
            self.ohlcvs[symbol][timeframe] = stored
        ohlcv = self.ohlcvs[symbol][timeframe]
        parsed = self.parse_ws_ohlcv(data)
        ohlcv.append(parsed)
        messageHash = 'candles:' + symbol + ':' + timeframe
        client.resolve([symbol, timeframe, ohlcv], messageHash)

    def parse_ws_ohlcv(self, ohlcv: object, market: Market = None) -> list:
        #
        #     {
        #         E: '1754519557526056',
        #         T: '2025-08-07T00:00:00',
        #         X: false,
        #         c: '3680.520000000',
        #         e: 'kline',
        #         h: '3681.370000000',
        #         l: '3667.650000000',
        #         n: 255,
        #         o: '3670.150000000',
        #         s: 'ETH_USDC',
        #         t: '2025-08-06T22:00:00',
        #         v: '62.2621000'
        #     },
        #
        return [
            self.parse8601(self.safe_string(ohlcv, 'T')),
            self.safe_number(ohlcv, 'o'),
            self.safe_number(ohlcv, 'h'),
            self.safe_number(ohlcv, 'l'),
            self.safe_number(ohlcv, 'c'),
            self.safe_number(ohlcv, 'v'),
        ]

