    async def watch_trades_for_symbols(self, symbols: list[str], since: Int = None, limit: Int = None, params: dict = {}) -> list[Trade]:
        """
        watches information on multiple trades made in a market

        https://docs.backpack.exchange/#tag/Streams/Public/Trade

        :param str[] symbols: unified symbol of the market to fetch trades for
        :param int [since]: the earliest time in ms to fetch trades for
        :param int [limit]: the maximum number of trade structures to retrieve
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param boolean [params.stock]: requires stock spot order-book markets, not RFQ markets
        :param str [params.source]: Venue only
        :returns dict: a `ticker structure <https://docs.ccxt.com/?id=ticker-structure>`
        """
        query = await self.prepare_ws_stock_params('watchTradesForSymbols', params)
        if self.markets is None:
            await self.load_markets()
        symbolsNormalized = self.market_symbols(symbols)
        symbolsLength = len(symbolsNormalized)
        if symbolsLength == 0:
            raise ArgumentsRequired(self.id + ' watchTradesForSymbols() requires a non-empty array of symbols')
        topics = []
        messageHashes = []
        for i in range(0, len(symbolsNormalized)):
            symbol = symbolsNormalized[i]
            market = self.market(symbol)
            self.ws_venue_market_id('watchTradesForSymbols', market, query)
            topics.append('trade.' + self.safe_string(market, 'id', ''))
            messageHashes.append('trades:' + symbol)
        trades = await self.watch_public(topics, messageHashes, self.omit(query, ['stock', 'source']))
        first = self.safe_dict(trades, 0)
        tradeSymbol = self.safe_string(first, 'symbol')
        limitResolved = limit
        if self.newUpdates:
            limitResolved = trades.getLimit(tradeSymbol, limit)
        result = self.filter_by_since_limit(trades, since, limitResolved, 'timestamp', True)
        return self.sort_by(result, 'timestamp')  # needed bcz of https://github.com/ccxt/ccxt/actions/runs/20755599389/job/59597208008?pr=27624#step:10:537

