    def handle_trades(self, client: Client, message: dict):
        #
        #     {
        #         data: {
        #             E: '1754601477746429',
        #             T: '1754601477744000',
        #             a: '5121860761',
        #             b: '5121861755',
        #             e: 'trade',
        #             m: false,
        #             p: '3870.25',
        #             q: '0.0008',
        #             s: 'ETH_USDC_PERP',
        #             t: 10782547
        #         },
        #         stream: 'trade.ETH_USDC_PERP'
        #     }
        #
        data = self.safe_dict(message, 'data', {})
        marketId = self.safe_string(data, 's')
        market = self.market(marketId)
        symbol = market['symbol']
        if not (symbol in self.trades):
            limit = self.safe_integer(self.options, 'tradesLimit', 1000)
            stored = ArrayCache(limit)
            self.trades[symbol] = stored
        cache = self.trades[symbol]
        trade = self.parse_ws_trade(data, market)
        cache.append(trade)
        messageHash = 'trades:' + symbol
        client.resolve(cache, messageHash)
        client.resolve(cache, 'trades')

    def parse_ws_trade(self, trade: dict, market: Market = None) -> Trade:
        #
        #     {
        #         E: '1754601477746429',
        #         T: '1754601477744000',
        #         a: '5121860761',
        #         b: '5121861755',
        #         e: 'trade',
        #         m: false,
        #         p: '3870.25',
        #         q: '0.0008',
        #         s: 'ETH_USDC_PERP',
        #         t: 10782547
        #     }
        #
        microseconds = self.safe_integer(trade, 'E', 0)
        timestamp = self.parse_to_int(microseconds / 1000)
        id = self.safe_string(trade, 't')
        marketId = self.safe_string(trade, 's')
        marketResolved = self.safe_market(marketId, market)
        isBuyerMaker = self.safe_bool(trade, 'm')
        side = None
        takerOrMaker = None
        if isBuyerMaker is not None:
            takerOrMaker = 'taker'
            if isBuyerMaker:
                side = 'sell'
            else:
                side = 'buy'
        price = self.safe_string(trade, 'p')
        amount = self.safe_string(trade, 'q')
        orderId = None
        if side == 'buy':
            orderId = self.safe_string(trade, 'b')
        else:
            orderId = self.safe_string(trade, 'a')
        return self.safe_trade({
            'info': trade,
            'id': id,
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'symbol': marketResolved['symbol'],
            'order': orderId,
            'type': None,
            'side': side,
            'takerOrMaker': takerOrMaker,
            'price': price,
            'amount': amount,
            'cost': None,
            'fee': {
                'currency': None,
                'cost': None,
            },
        }, marketResolved)

